'use strict';
const cats=['Plumbing','Electrical','Painting','Carpentry','Masonry','Gardening','Cleaning','Mechanic'];
const paths=['M4 3h9v4H9v5h7v-2h4v7H5V7H4z','M14 2 5 14h6l-1 8 9-13h-6z','M4 4h13v6H4z M17 7h3v6h-8v3 M10 16h4v6h-4z','M3 15 13 5l6 6-9 9-2-1-1-2-2-1z M14 6l3-3 5 5-3 3','M2 6h20v13H2z M2 12h20 M9 6v6 M15 12v7','M4 20c9 0 16-7 15-16C10 3 4 9 6 16 M4 21l11-12','M4 21l2-8 7-2 3 3-4 7z M13 11l6-8 2 2-6 8 M7 17l-1 4 M10 17l-1 4','M20 4a6 6 0 0 1-7 8l-7 8a2 2 0 0 1-3-3l8-8a6 6 0 0 1 8-7l-4 4 3 2z'];
const pros=[['Nimal Perera',0,3200,4.8,2.4],['Kavindi Silva',1,2800,4.9,3.1],['Ravi Fernando',0,2400,4.5,5.2],['Asha Dias',2,3500,4.7,3.7],['Dilan Perera',3,3600,4.6,2.1],['Isuru Silva',4,4200,4.8,4.1],['Saman Deen',5,2300,4.7,1.5],['Tharushi Jay',6,2000,4.8,2.9],['Amal Costa',7,3100,4.7,2.2]];
const app=document.querySelector('#app'),modal=document.querySelector('dialog'),inside=document.querySelector('#inside');
let jobs=JSON.parse(localStorage.getItem('servora.requests.v1')||'[]'),view='discover',category='All',priority='Rating';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>'LKR '+Number(x).toLocaleString('en-US');
const icon=i=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+paths[i]+'"/></svg>';
function persist(){localStorage.setItem('servora.requests.v1',JSON.stringify(jobs));}
function show(html){inside.innerHTML=html;if(!modal.open)modal.showModal();}
function navigate(v){view=v;render();}
function providerCard(p){return '<article class="pro"><span class="avatar">'+p[0].split(' ').map(n=>n[0]).join('')+'</span><h3>'+p[0]+'</h3><small>'+cats[p[1]]+' · '+p[4]+' km away</small><div class="tag">★ '+p[3]+'　·　From '+money(p[2])+'</div><button class="outline" data-person="'+pros.indexOf(p)+'">View profile</button></article>';}
function mapArt(){return '<canvas class="map" id="map" aria-label="Illustrated street map of nearby services"></canvas>';}
function drawMap(){const cv=document.querySelector('#map');if(!cv)return;cv.width=560;cv.height=380;const x=cv.getContext('2d');x.fillStyle='#d9e7c3';x.fillRect(0,0,560,380);x.save();x.translate(5,-30);x.rotate(-.2);for(let i=-1;i<9;i++)for(let j=-1;j<8;j++){x.fillStyle=(i+j)%3?'#c7dcb5':'#abc99f';x.fillRect(i*83+4,j*71+4,75,63);x.fillStyle='#dce8cd';x.fillRect(i*83+13,j*71+12,27,22);}x.strokeStyle='#f3f1d9';x.lineWidth=14;x.beginPath();x.moveTo(-50,320);x.bezierCurveTo(110,330,200,40,600,130);x.stroke();x.restore();x.strokeStyle='#68885b';x.setLineDash([5,7]);x.lineWidth=3;x.beginPath();x.moveTo(148,224);x.lineTo(278,224);x.lineTo(328,126);x.stroke();x.setLineDash([]);for(const [px,py,label] of [[148,220,'⌂'],[330,125,'✦'],[447,266,'⌁']]){x.fillStyle='#2c4c38';x.beginPath();x.arc(px,py-24,25,0,7);x.fill();x.beginPath();x.moveTo(px-11,py-6);x.lineTo(px,py+9);x.lineTo(px+11,py-6);x.fill();x.fillStyle='#e5f6bc';x.font='bold 26px Arial';x.textAlign='center';x.fillText(label,px,py-15);}}
function render(){const title={discover:'Discover',requests:'My requests',providers:'Professionals'}[view];document.querySelector('#crumb').textContent=title;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
if(view==='discover'){app.innerHTML='<div class="hero"><div class="herotext"><div class="kicker">LOCAL SERVICE DESK</div><h1>Find your local pro.</h1><p>Compare nearby professionals and choose the right person for the job.</p><button class="btn" data-new>＋　New request</button></div>'+mapArt()+'</div><div class="heading"><h2>Browse services</h2><span class="tag">8 categories</span></div><div class="grid">'+cats.map((c,i)=>'<button class="tile" data-cat="'+i+'"><span class="ico">'+icon(i)+'</span><strong>'+c+'</strong></button>').join('')+'</div><div class="heading"><h2>Nearby professionals</h2><button class="chip" data-view="providers">View all →</button></div><div class="pros">'+pros.slice(0,3).map(providerCard).join('')+'</div>';drawMap();}
if(view==='providers'){const found=pros.filter(p=>category==='All'||cats[p[1]]===category).sort((a,b)=>priority==='Rating'?b[3]-a[3]:priority==='Price'?a[2]-b[2]:a[4]-b[4]);app.innerHTML='<h1>Professionals</h1><div class="filters"><label>Service<select id="category">'+['All',...cats].map(x=>'<option '+(x===category?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>Sort by<select id="priority">'+['Rating','Price','Distance'].map(x=>'<option '+(x===priority?'selected':'')+'>'+x+'</option>').join('')+'</select></label></div><div class="pros">'+found.map(providerCard).join('')+'</div>';}
if(view==='requests'){app.innerHTML='<div class="heading"><h2>My requests</h2><button class="btn" data-new>＋ New request</button></div>'+(jobs.length?jobs.map((j,i)=>'<button class="job" data-job="'+i+'"><h3>'+esc(j.title)+'</h3><small>'+esc(j.cat)+' · '+esc(j.area)+' · '+money(j.budget)+'</small><b>'+esc(j.status)+'</b></button>').join(''):'<p>You have no requests yet. Describe a task to see sample quotes.</p>');}
app.insertAdjacentHTML('beforeend','<p class="warning">Interactive demo · Sample providers and quotes. Requests are saved on this browser.</p>');}
function newRequest(cat='Plumbing'){show('<h2>New service request</h2><form id="request"><label>Service<select name="cat">'+cats.map(x=>'<option '+(x===cat?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>Task title<input name="title" required maxlength="100" placeholder="Repair a leaking kitchen tap"></label><label>Task details<textarea name="details" required maxlength="500"></textarea></label><label>Town or area<input name="area" value="Colombo" required maxlength="80"></label><label>Budget (LKR)<input name="budget" type="number" min="1" required></label><button class="btn">Create request</button></form>');}
function details(i){let j=jobs[i];show('<h2>'+esc(j.title)+'</h2><p>'+esc(j.details)+'</p><small>'+esc(j.area)+' · '+money(j.budget)+' · '+esc(j.status)+'</small>'+(j.status==='Open'?'<h3>Sample quotations</h3>'+pros.filter(p=>cats[p[1]]===j.cat).map(p=>'<div class="jobbox">'+p[0]+' · '+money(p[2])+' <button class="outline" data-accept="'+i+','+pros.indexOf(p)+'">Choose</button></div>').join(''):'<p>Assigned to '+esc(j.person)+'</p>')+(['Booked','In progress'].includes(j.status)?'<button class="btn" data-step="'+i+'">'+(j.status==='Booked'?'Start job as provider':'Submit completed work')+'</button>':'')+(j.status==='Awaiting review'?'<form id="review" data-id="'+i+'"><label>Stars<select name="stars">'+[5,4,3,2,1].map(v=>'<option>'+v+'</option>').join('')+'</select></label><label>Feedback<textarea name="feedback" required></textarea></label><button class="btn">Confirm completion</button></form>':'')+(j.feedback?'<p>★ '+j.stars+' · '+esc(j.feedback)+'</p>':''));}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.view){if(d.view==='providers')category='All';navigate(d.view);}if('new'in d)newRequest();if('cat'in d){category=cats[d.cat];navigate('providers');}if('person'in d){const p=pros[d.person];show('<h2>'+p[0]+'</h2><p>'+cats[p[1]]+' · Colombo · '+p[4]+' km away</p><p>★ '+p[3]+' · Starting rate '+money(p[2])+'</p><button class="btn" data-requestcat="'+p[1]+'">Request this service</button>');}if('requestcat'in d)newRequest(cats[d.requestcat]);if('job'in d)details(+d.job);if('accept'in d){const [i,p]=d.accept.split(',').map(Number);jobs[i].person=pros[p][0];jobs[i].status='Booked';persist();render();details(i);}if('step'in d){const i=+d.step;jobs[i].status=jobs[i].status==='Booked'?'In progress':'Awaiting review';persist();render();details(i);}});
document.addEventListener('change',e=>{if(e.target.id==='priority')priority=e.target.value;else if(e.target.id==='category')category=e.target.value;else return;render();});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));if(f.id==='request'){jobs.unshift({...data,status:'Open'});persist();navigate('requests');details(0);}if(f.id==='review'){Object.assign(jobs[f.dataset.id],data,{status:'Completed'});persist();render();details(+f.dataset.id);}});render();
